class Bundle:
    """What every adapter returns: artifacts, manifest patch, cost by tier.

    ``cost`` is what the call ACTUALLY spent, per tier. ``predicted_cost`` is
    what the call declared it would be allowed to spend, quoted up-front from
    the declared limits (before a single evaluation runs). ``delta_cost`` is
    actual ``-`` predicted: legitimately negative when a search exits early
    (e.g. a plateau kill), and that gap is why the delta is recorded instead
    of the two fields being forced to agree.
    """

    artifacts: List[Artifact] = field(default_factory=list)
    manifest_patch: Dict[str, Any] = field(default_factory=dict)
    cost: Dict[int, float] = field(
        default_factory=lambda: {TIER_ZERO: 0.0, TIER_ONE: 0.0, TIER_TWO: 0.0}
    )
    predicted_cost: Dict[int, float] = field(
        default_factory=lambda: {TIER_ZERO: 0.0, TIER_ONE: 0.0, TIER_TWO: 0.0}
    )
    delta_cost: Dict[int, float] = field(
        default_factory=lambda: {TIER_ZERO: 0.0, TIER_ONE: 0.0, TIER_TWO: 0.0}
    )

    def total_cost(self) -> float:
        return sum(self.cost.values())

    def total_predicted_cost(self) -> float:
        return sum(self.predicted_cost.values())"}

