        cap = self.limits.get(tier)
        if cap is None:
            return None
        return max(0.0, cap - self.spent.get(tier, 0.0))

    def quote(self, evals_by_tier: Dict[int, int]) -> Dict[int, float]:
        """Cost of running ``evals_by_tier`` evaluations, at the ledger's rate.

        This is the honest upper estimate of a declared search: the caller
        declares how many evaluations it MAY perform per tier, and this prices
        that declaration. It never charges anything.
        """
        out: Dict[int, float] = {}
        for tier, n in evals_by_tier.items():
            out[int(tier)] = float(n) * float(self.costs.get(int(tier), 0.0))
        return out

    def remaining_for(
        self, tier: int, units: float
    ) -> Optional[float]:
        """How much more a tier can absorb before its cap is hit.

        ``None`` when the tier is uncapped (spend there is admitted, but still
        recorded). Raises :class:`BudgetExceeded` iff an admission check for
        ``units`` would fail — i.e. the budget is finite AND ``units`` does not
        fit under the cap, leaving the rest for the caller to decide without
        having spent anything.
        """
        cap = self.limits.get(tier)
        if cap is None:
            return None
        headroom = max(0.0, cap - self.spent.get(int(tier), 0.0))
        if units > headroom:
            raise BudgetExceeded(
                f"tier {tier} cannot admit {units:.3f} more units "
                f"({self.spent.get(int(tier), 0.0):.3f} spent, cap {cap:.3f})"
            )
        return headroom"}

