    def predict_cost(self, payload: Dict[str, Any], budget: Optional["Budget"]):
        """Up-front quote of this call's worst case, in cost units per tier.

        Derived from what the call *declared* (its limits) and the ledger's
        per-tier rates; computed BEFORE any work. Returns ``None`` (the
        default) when the adapter has no meterable declaration to quote --
        the call is then charged purely on what it reports.
        """
        return None

    @abstractmethod
    def _exec(self, manifest, budget, **inputs) -> Bundle:
        raise NotImplementedError

    def run(self, manifest, budget, **inputs) -> Bundle:
        # --- budget ledger (Phase 2, item 3) ---------------------------------
        # 1) QUOTE: the worst case the call declared, per the ledger's rates.
        # 2) ADMIT: require the quote to fit in the REMAINING budget, before a
        #    single unit of work runs. A call that cannot fit fails here,
        #    spending and evaluating nothing (BudgetExceeded).
        # 3) CHARGE: whatever the adapter actually ran, per tier. Because the
        #    quote is an upper bound, this can never exceed what was admitted.
        # The predicted and the actual are both recorded on the Bundle and in
        # the manifest; the delta between them is the cost of exiting early.
        predicted = self.predict_cost(inputs, budget)
        if predicted is None:
            predicted = {}
        predicted = {int(t): float(a) for t, a in predicted.items()}
        if budget is not None:
            for tier, amount in predicted.items():
                if amount > 0.0:
                    budget.remaining_for(tier, amount)
        bundle = self._exec(manifest, budget, **inputs)

        # charge the budget for each tier used (validates per-tier limits)
        budget_exceeded = False
        if budget is not None:
            try:
                for tier, cost in bundle.cost.items():
                    budget.spend(int(tier), float(cost))
            except BudgetExceeded:
                budget_exceeded = True
                # Leave the ledger alone; the record below shows what was
                # admitted, what ran, and that it did not fit."}

